'use strict';
// Shared task tracking; result navigation always resolves the business type first.
const tcBase={tasksPage,handleAction,modalContent,openTask,render};
const TC_TOOLS={extract:{type:1,noun:'提取信息',hint:'核对字段值与原文，可导出信息表'},contract:{type:2,noun:'合同检查',hint:'查看条款检查、基础信息及分析依据'},timeline:{type:3,noun:'事项时间轴',hint:'按事项日期查看事件与原文依据'},word:{type:4,noun:'词云与词频',hint:'查看词频分布及词语来源'},theme:{type:5,noun:'主题归纳',hint:'查看归纳主题与基础信息'},engineering:{type:6,noun:'项目关系候选',hint:'核对重复项目、主子项目及源行'},meeting:{type:7,noun:'会议与议题',hint:'查看会议议题，可继续风险分析或问答'},risk:{type:8,noun:'风险检查线索',hint:'按风险点核对线索与原文依据'},association:{type:9,noun:'两表关联候选',hint:'核对候选关系、分数与对应源行'},bidding:{type:10,noun:'招投标检查',hint:'按项目核对招标、投标及联合检查结果'},prepaid:{type:10,noun:'计费约定与费用',hint:'核对计费约定、基数、公式及费用报告'}};
const TC_BIZ={contractCompleteness:'contract',engineeringProject:'engineering',engineering_project_data_consistency:'engineering',associationDegreeTwoTables:'association',association_degree_two_tables:'association',wordCloud:'word',wordCloudAnalysis:'word',meeting_minutes:'meeting',meetingMinutes:'meeting',biz_topic_summary:'theme',agent_info_extraction:'theme',agent_info_extraction_and_topic_summary:'theme',themeAnalysisExtract:'theme',riskPointAnalysis:'risk',prepaidExpenses:'prepaid',timelineAnalysis:'timeline',timeline_analysis:'timeline',biddingAnalysis:'bidding'};
Object.assign(STATUS,{queued:['排队中',''],completed:['分析完成','green'],running:['分析中','blue'],partial:['部分完成','amber'],failed:['分析失败','red'],stopped:['已终止','']});
const tcView={group:'all',size:10,kind:'all',from:'',to:'',scroll:0,infoTab:'overview'};
function tcResolve(t){const biz=t.biz_type||t.BIZ_TYPE;if(TC_BIZ[biz])return TC_BIZ[biz];if(TC_TOOLS[t.toolId])return t.toolId;const type=Number(t.task_type??t.TASK_TYPE);return type===10?null:Object.keys(TC_TOOLS).find(id=>TC_TOOLS[id].type===type)||null;}
function tcMerge(t){return t.kind==='merge-export'||!!t.is_merge_export_task;}
function tcBusy(t){return t.status!=='stopped'&&(['queued','running'].includes(t.status)||t.summaryGenerating);}
function tcAttention(t){return t.status!=='stopped'&&(['partial','failed','awaiting'].includes(t.status)||t.summaryFailed);}
function tcLabel(t){if(tcMerge(t))return ({queued:['排队中',''],running:['导出中','blue'],completed:['导出完成','green'],failed:['导出失败','red'],stopped:['已终止','']})[t.status]||['状态待确认',''];if(t.status==='stopped')return STATUS.stopped;if(t.summaryGenerating)return ['归纳中','blue'];if(t.summaryFailed)return ['归纳未完成','amber'];return STATUS[t.status]||['状态待确认',''];}
function tcRows(t){return Array.isArray(t.result)?t.result:[];}
function tcCount(t){const ids=[...new Set(t.ids||[])],ok=new Set((t.successIds||[]).filter(id=>ids.includes(id))),fail=new Set((t.failedIds||[]).filter(id=>ids.includes(id)&&!ok.has(id)));return {total:ids.length,ok:ok.size,fail:fail.size,pending:Math.max(0,ids.length-ok.size-fail.size)};}
function tcOutput(t){const rows=tcRows(t),n=rows.length,id=tcResolve(t),unique=k=>new Set(rows.map(r=>r[k]).filter(Boolean)).size;if(tcMerge(t))return {text:t.status==='completed'?(t.artifacts?.length||0)+' 个导出文件':t.status==='stopped'?'导出已终止':'合并 '+(t.sourceTaskIds?.length||0)+' 项任务',hint:t.status==='completed'?'下载 Excel / SQL 结果文件':'保留来源任务及字段映射'};if(tcBusy(t))return {text:t.summaryGenerating?'基础信息已保留':'正在生成'+(TC_TOOLS[id]?.noun||'分析结果'),hint:t.summaryGenerating?'仅重新归纳主题，不重复提取资料':t.status==='queued'?'等待执行，尚未开始 AI 分析':'完成后可查看结果与来源'};if(t.status==='failed'||t.status==='stopped')return {text:n?'已保留 '+n+' 条阶段结果':t.status==='failed'?'未生成可用结果':'任务已终止',hint:t.status==='failed'?'查看失败原因，再重试失败部分':'可查看任务信息，或调整后重新分析'};if(t.status==='awaiting')return {text:'计费约定已提取',hint:'待填写计费基数，尚未生成费用报告'};if(!n)return {text:'未返回可展示结果',hint:'查看任务信息与资料范围，勿据此判断无问题'};const texts={extract:n+' 份资料 · '+(t.config?.fieldDefs?.length??t.config?.fields?.length??0)+' 个提取字段',word:n+' 个词语 · '+rows.reduce((s,r)=>s+(Number(r.count)||0),0)+' 次出现',theme:t.summaryFailed?'基础信息 '+unique('doc')+' 份 · 归纳未完成':unique('topic')+' 类主题 · 基础信息 '+unique('doc')+' 份',timeline:n+' 条事项 · '+rows.filter(r=>!r.date).length+' 条日期未提取到',meeting:unique('doc')+' 份会议资料 · '+n+' 条议题',risk:n+' 项检查 · '+rows.filter(r=>r.findingStatus==='nohit').length+' 项未匹配线索',contract:n+' 项条款检查',bidding:n+' 项招投标检查',engineering:n+' 组项目关系候选',association:n+' 组关联候选',prepaid:t.fee!=null?'计算费用 '+Number(t.fee).toLocaleString('zh-CN',{maximumFractionDigits:2})+' 元':'计费约定已提取'};return {text:texts[id]||n+' 条返回结果',hint:t.summaryFailed?'可先查看基础信息，或重试归纳阶段':TC_TOOLS[id]?.hint||'查看任务信息确认业务类型'};}
function tcPrimary(t){if(tcMerge(t))return t.status==='completed'?'下载文件':tcBusy(t)?'查看进度':'查看导出任务';if(t.status==='awaiting')return '填写计费基数';if(tcBusy(t))return '查看进度';if(t.status==='stopped')return '查看任务';if(t.status==='failed')return '处理失败';if(t.summaryFailed)return '查看基础信息';return '查看结果';}
function tcDate(v){const d=new Date(v);return Number.isNaN(+d)?'—':d.toLocaleString('zh-CN',{hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function tcAll(){return state.tasks.filter(t=>(state.taskStatus==='all'||t.status===state.taskStatus)&&(state.taskTool==='all'||tcResolve(t)===state.taskTool)&&(tcView.kind==='all'||tcMerge(t)===(tcView.kind==='export'))&&(!tcView.from||String(t.created).slice(0,10)>=tcView.from)&&(!tcView.to||String(t.created).slice(0,10)<=tcView.to)&&((t.name||'')+' '+(t.notes||'')).toLowerCase().includes((state.taskQuery||'').toLowerCase()));}
function tcInGroup(t,g=tcView.group){return g==='all'||g==='processing'&&tcBusy(t)||g==='attention'&&tcAttention(t)||g==='done'&&t.status==='completed'&&!t.summaryFailed&&!tcBusy(t)||g==='stopped'&&t.status==='stopped';}
function tcSelectable(t){const selected=taskChecked.map(id=>state.tasks.find(t=>t.id===id)).filter(Boolean);return !tcMerge(t)&&!!tcResolve(t)&&(!selected.length||(t.agent_id&&selected[0].agent_id?String(t.agent_id)===String(selected[0].agent_id):tcResolve(t)===tcResolve(selected[0])));}
function tcProgress(t){const c=tcCount(t),pct=t.summaryGenerating||t.progress===null||t.progress===undefined||t.progress===''||!Number.isFinite(+t.progress)?null:Math.min(100,Math.max(0,+t.progress));let text=tcMerge(t)?E(t.phase||'正在准备导出'):t.status==='queued'?'等待开始':t.status==='stopped'?E(t.phase||'用户终止任务'):t.summaryFailed?'基础信息已提取，主题归纳失败':t.summaryGenerating?'正在重新归纳主题':t.status==='awaiting'?'第一阶段完成，等待填写基数':E(t.phase||'');return (t.status==='completed'&&!t.summaryFailed||tcMerge(t)&&t.status==='stopped'?'':'<div class="tc-phase">'+text+'</div>')+(tcBusy(t)?'<div class="tc-progress" role="progressbar" aria-label="任务整体进度" aria-valuemin="0" aria-valuemax="100" '+(pct===null?'':'aria-valuenow="'+pct+'"')+'><i style="width:'+(pct??0)+'%"></i></div><small>'+(pct===null?(t.summaryGenerating?'归纳阶段进度待更新':'处理进度待更新'):'整体进度 '+pct+'%')+'</small>':!tcMerge(t)&&c.total?'<small>资料：成功 '+c.ok+' · 失败 '+c.fail+(c.pending?' · '+(t.status==='stopped'?'未处理':'待处理')+' '+c.pending:'')+'</small>':'');}
function tcRow(t){const id=tcResolve(t),meta=tool(id),o=tcOutput(t),a='data-id="'+E(t.id)+'"';return '<tr data-tc-row="'+E(t.id)+'"><td><input type="checkbox" data-tc-check="'+E(t.id)+'" aria-label="选择任务 '+E(t.name)+'" '+(taskChecked.includes(t.id)?'checked ':'')+(!tcSelectable(t)?'disabled title="请选择相同工具的分析任务；合并导出任务不能再次合并"':'')+'></td><td><button class="tc-name" data-action="tc-open" '+a+' title="'+E(t.name)+'">'+E(t.name||'未命名任务')+'</button><div class="tc-note" title="'+E(t.notes||'')+'">'+E(t.notes||'')+'</div></td><td><div class="tc-tool" title="'+E(tcMerge(t)?'合并导出':meta?.name||'待确认工具')+'">'+I(tcMerge(t)?'download':meta?.icon||'tasks','icon-sm')+'<span>'+E(tcMerge(t)?'合并导出':meta?.name||'待确认工具')+'</span></div>'+(tcMerge(t)?'<small>'+E(meta?.name||'')+' · '+(t.sourceTaskIds?.length||0)+' 项任务</small>':'<small>'+tcCount(t).total+' 份资料</small>')+'</td><td>'+tag(...tcLabel(t))+tcProgress(t)+'</td><td><strong class="tc-output">'+E(o.text)+'</strong><small>'+E(o.hint)+'</small></td><td><time>'+tcDate(t.created)+'</time></td><td class="tc-actions"><div>'+A(tcPrimary(t),'tc-open',a)+'<details class="tc-row-more"><summary aria-label="更多操作 '+E(t.name)+'" title="更多操作">'+I('more')+'</summary><div class="tc-row-menu">'+B(I('file','icon-sm')+'任务信息','tc-info','ghost',a)+(!tcMerge(t)?B(I('edit','icon-sm')+'修改任务备注','tc-notes','ghost',a):'')+(tcBusy(t)?B(I('pause','icon-sm')+'终止任务','tc-stop','ghost danger',a):B(I('trash','icon-sm')+'删除记录','delete-task','ghost danger',a))+'</div></details></div></td></tr>';}
tasksPage=function(){taskChecked=taskChecked.filter(id=>state.tasks.some(t=>t.id===id&&!tcMerge(t)));const all=tcAll(),rows=all.filter(t=>tcInGroup(t));state.taskPage=Math.max(1,Math.min(state.taskPage||1,Math.ceil(rows.length/tcView.size)||1));const n=taskChecked.length;return '<div class="tc-page"><header class="tc-header"><div><h1>任务中心</h1><span>跟踪 AI 分析进度，查看各工具结果与来源</span></div>'+B(I('folder','icon-sm')+'前往资料管理','nav-library','sm')+'</header><section class="tc-card"><div class="tc-toolbar"><div class="search">'+I('search','icon-sm')+'<input id="tc-query" aria-label="搜索任务" placeholder="搜索任务名称或备注" data-input="task-query" value="'+E(state.taskQuery||'')+'"></div><select aria-label="工具类型" data-change="task-tool"><option value="all">全部工具</option>'+TOOLS.map(t=>'<option value="'+t.id+'" '+(state.taskTool===t.id?'selected':'')+'>'+t.name+'</option>').join('')+'</select><select aria-label="任务状态" data-change="task-status"><option value="all">全部状态</option>'+Object.entries(STATUS).map(([id,[label]])=>'<option value="'+id+'" '+(state.taskStatus===id?'selected':'')+'>'+label+'</option>').join('')+'</select><details class="tc-filter-more"><summary class="btn sm">筛选'+I('down','icon-sm')+'</summary><div><label>任务类型<select data-tc-filter="kind" aria-label="任务类型">'+[['all','全部任务'],['analysis','工具分析'],['export','合并导出']].map(([id,n])=>'<option value="'+id+'" '+(tcView.kind===id?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>创建日期<input aria-label="起始日期" type="date" data-tc-filter="from" value="'+tcView.from+'">至<input aria-label="结束日期" type="date" data-tc-filter="to" value="'+tcView.to+'"></label>'+B('重置筛选','tc-reset','sm')+'</div></details>'+B(I('refresh','icon-sm')+'刷新','tc-refresh','sm')+'<span class="tc-spacer"></span>'+B(I('download','icon-sm')+'合并导出'+(n?' ('+n+')':''),'merge-export','sm',n>=2?'':'disabled')+'</div><div class="tc-tabs" role="tablist" aria-label="任务分类">'+[['all','全部'],['processing','处理中'],['attention','需跟进'],['done','已完成'],['stopped','已终止']].map(([id,label])=>'<button role="tab" aria-selected="'+(tcView.group===id)+'" class="'+(tcView.group===id?'active':'')+'" data-action="tc-group" data-group="'+id+'">'+label+'<strong>'+all.filter(t=>tcInGroup(t,id)).length+'</strong></button>').join('')+'</div>'+(n?'<div class="tc-selection">已选 <strong>'+n+'</strong> 项'+E(tool(tcResolve(state.tasks.find(t=>t.id===taskChecked[0])))?.name||'')+'任务 · 可跨页选择'+A('清空选择','clear-task-check')+'<span>合并时只导出已有且可访问的结果</span></div>':'')+'<div class="tc-table-scroll"><table class="table tc-table"><colgroup><col class="tc-check-col"><col class="tc-name-col"><col class="tc-tool-col"><col class="tc-status-col"><col class="tc-result-col"><col class="tc-time-col"><col class="tc-action-col"></colgroup><thead><tr><th>选择</th><th>任务名称</th><th>使用工具 / 范围</th><th>分析状态与进度</th><th>结果与后续操作</th><th>创建时间</th><th>操作</th></tr></thead><tbody>'+pageItems(rows,state.taskPage,tcView.size).map(tcRow).join('')+'</tbody></table>'+(!rows.length?'<div class="tc-empty">'+I('tasks')+'<h2>'+(state.tasks.length?'没有符合条件的任务':'分析任务将在这里集中展示')+'</h2><p>'+(state.tasks.length?'调整工具、状态或关键词，查找其他任务。':'从资料管理选择分析工具，提交后即可在这里跟踪进度、查看结果。')+'</p>'+B(state.tasks.length?'重置筛选':'前往资料管理',state.tasks.length?'tc-reset':'nav-library','sm')+'</div>':'')+'</div><footer class="tc-pagination"><span>共 <strong>'+rows.length+'</strong> 项</span><div><select aria-label="任务每页条数" data-tc-filter="size">'+[10,20,50].map(v=>'<option '+(tcView.size===v?'selected':'')+'>'+v+'</option>').join('')+'</select>'+B(I('back','icon-sm'),'tc-page','ghost sm','data-step="-1" aria-label="上一页" '+(state.taskPage<=1?'disabled':''))+'<span>'+state.taskPage+' / '+Math.max(1,Math.ceil(rows.length/tcView.size))+'</span>'+B(I('chevron','icon-sm'),'tc-page','ghost sm','data-step="1" aria-label="下一页" '+(state.taskPage*tcView.size>=rows.length?'disabled':''))+'</div></footer></section><p class="tc-footnote">“分析完成”表示 AI 已返回本次结果；风险线索与候选关系需结合原文核验。资料解析状态与工具分析状态分别记录。</p></div>';};
function tcConfig(t){const c=t.config||{},id=tcResolve(t),defs=c.fieldDefs||[],items=[['执行方式',+t.executionMode===2?'后台执行':'当前页面执行'],['提取 / 分析模板',c.template||'本次自定义配置']];if(id==='extract'){items.push(['合并附件',c.merge?'包含附件内容':'仅主文件'],['提取字段',(defs.length?defs.map(f=>f.name):c.fields||[]).join('、')||'未记录']);}else if(id==='word')items.push(['展示词数上限',c.top],['停用词',(t.stopwords||[]).join('、')||'无'],['用户新词',(t.newwords||[]).join('、')||'无']);else if(id==='association')items.push(['两张表',(t.tableAName||'表一')+' ↔ '+(t.tableBName||'表二')],['候选阈值',String(c.threshold??'未记录')+' / 5']);else if(id==='prepaid')items.push(['计费基数',t.base?Number(t.base).toLocaleString()+' 元':'待填写'],['计算费用',t.fee==null?'未生成':Number(t.fee).toLocaleString()+' 元']);if(c.stages)Object.entries(c.stages).forEach(([k,v])=>items.push([v.template||k,v.content||'未记录']));else if(c.prompt)items.push(['本次分析要求',c.prompt]);return '<dl class="tc-config">'+items.map(([n,v])=>'<dt>'+E(n)+'</dt><dd>'+E(v??'未记录')+'</dd>').join('')+'</dl>'+(defs.length?simpleTable(['提取字段','提取说明'],defs.map(f=>[E(f.name),E(f.description||'按字段名称提取')]),true):'');}
function tcInfo(t){if(tcView.infoTab==='sources'&&typeof wnTaskSources==='function')return wnTaskSources(t);const c=tcCount(t),o=tcOutput(t),tab=tcView.infoTab;return modalFrame('任务信息',E(t.name),'<div class="tc-info-status">'+tag(...tcLabel(t))+'<span>'+E(o.text)+'</span></div><div class="tc-info-tabs">'+[['overview','进度与结果'],['sources','分析资料 ('+c.total+')'],['config','执行配置']].map(([k,n])=>B(n,'tc-info-tab',tab===k?'soft sm':'ghost sm','data-tab="'+k+'"')).join('')+'</div>'+(tab==='sources'?'<p class="hint">保留本次资料范围；查看原文仍按当前权限判断。</p>'+simpleTable(['文件名称','资料位置','工具分析状态','原文'],(t.ids||[]).map(id=>{const d=file(id),status=t.successIds?.includes(id)?'分析成功':t.failedIds?.includes(id)?'分析失败':t.status==='stopped'?'未处理':'待处理';return[E(d?.name||'原资料已移除'),E(d?d.space+' / '+(folderPath(d.folder)||'根目录'):'—'),tag(status,status==='分析失败'?'red':status==='分析成功'?'green':''),d&&!d.deleted&&auditFileAccess(d).preview?A('查看原文','source','data-id="'+E(id)+'"'):'当前不可查看'];}),true):tab==='config'?'<p class="hint">执行时的配置快照；修改要求请从对应工具复制新建。</p>'+tcConfig(t):'<div class="tc-info-stage"><h3>当前阶段</h3>'+tcProgress(t)+'</div><div class="tc-info-outcome"><h3>'+E(TC_TOOLS[tcResolve(t)]?.noun||'返回结果')+'</h3><p>'+E(o.text)+'</p><p class="hint">'+E(o.hint)+'</p>'+(['completed','partial'].includes(t.status)?'<p class="hint">AI 返回内容供审计核验使用，不表示问题或候选关系已经确认。</p>':'')+'</div>'+(['failed','partial','stopped'].includes(t.status)?'<div class="tc-followup"><h3>'+(t.summaryFailed?'归纳阶段需跟进':t.status==='stopped'?'已终止执行':'失败处理')+'</h3><p>'+E(t.error||t.errorMessage||t.failureMessage||(t.summaryFailed?'基础信息已保留，可仅重试主题归纳。':t.status==='stopped'?'保留已返回的结果与执行配置，尚未处理的资料未完成分析。':c.fail?'有 '+c.fail+' 份资料未分析成功。进入对应工具可查看失败资料并重试。':'未收到具体失败原因，请刷新任务状态或核对执行日志。'))+'</p></div>':'')+'<dl class="tc-meta"><dt>任务编号</dt><dd>'+E(t.id)+'</dd><dt>使用工具</dt><dd>'+E(tool(tcResolve(t))?.name||'待确认业务类型')+'</dd><dt>创建时间</dt><dd>'+tcDate(t.created)+'</dd><dt>任务备注</dt><dd>'+E(t.notes||'未填写')+'</dd></dl>'),'<span class="tc-modal-note">任务记录与原资料分别管理</span><div class="row">'+B('关闭','close-modal','sm')+(tcResolve(t)?B(t.status==='failed'?'进入工具处理':tcPrimary(t),'tc-result','primary sm','data-id="'+E(t.id)+'"'):'')+'</div>','tc-info-dialog');}
openTask=function(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;if(tcMerge(t))return openModal('tc-export-detail',{id});const tid=tcResolve(t);if(!tid){tcView.infoTab='overview';return openModal('tc-info',{id});}t.toolId=tid;resultFilter='';resultScope='all';if(AW_IDS.includes(tid)){av(tid).tab='main';av(tid).resultQuery='';av(tid).resultScope='all';if(t.summaryFailed)av(tid).tab='base';}tcBase.openTask(id);};
modalContent=function(){if(modal==='tc-info'){const t=state.tasks.find(t=>t.id===modalData.id);return t?tcInfo(t):tcBase.modalContent();}if(modal==='tc-notes'){const t=state.tasks.find(t=>t.id===modalData.id);return modalFrame('修改任务备注',E(t?.name),'<label class="field"><span>任务备注 <span class="muted">（选填）</span></span><textarea id="tc-notes" rows="4" maxlength="500" placeholder="记录本次分析目的或审计关注">'+E(t?.notes||'')+'</textarea></label><p class="hint">仅修改任务备注，不改变分析资料、配置与结果。</p>',B('取消','close-modal')+B('保存','tc-notes-save','primary'),'small');}if(modal==='tc-merge')return tcMergeModal();if(modal==='tc-export-detail')return tcExportDetail(state.tasks.find(t=>t.id===modalData.id));return tcBase.modalContent();};
handleAction=function(action,el){const id=el.dataset.id,t=state.tasks.find(x=>x.id===id);switch(action){case 'tc-group':tcView.group=el.dataset.group;state.taskPage=1;tcView.scroll=0;render();return;case 'tc-reset':state.taskQuery='';state.taskStatus='all';state.taskTool='all';state.taskPage=1;Object.assign(tcView,{group:'all',kind:'all',from:'',to:'',scroll:0});render();return;case 'tc-page':state.taskPage+=Number(el.dataset.step);tcView.scroll=0;render();return;case 'tc-refresh':render();toast('已刷新本页面任务状态。');return;case 'tc-open':if(!t)return;if(tcMerge(t))return openTask(id);if(['failed','stopped'].includes(t.status)){tcView.infoTab='overview';return openModal('tc-info',{id});}return openTask(id);case 'tc-result':return openTask(id);case 'tc-info':tcView.infoTab='overview';return openModal('tc-info',{id});case 'tc-info-tab':tcView.infoTab=el.dataset.tab;paintModal();return;case 'tc-notes':return openModal('tc-notes',{id});case 'tc-notes-save':{const task=state.tasks.find(x=>x.id===modalData.id);task.notes=$('#tc-notes').value.trim();persist();closeModal();render();toast('任务备注已保存。');return;}case 'tc-stop':if(!t||!tcBusy(t))return;return openModal('confirm',{title:'终止任务？',text:'终止后保留已返回的结果、资料范围与配置；尚未完成的分析不会继续。原资料保留。',label:'终止任务',action:'tc-stop-confirm',attrs:'data-id="'+E(id)+'"'});case 'tc-stop-confirm':if(!t||!tcBusy(t)){closeModal();render();toast('任务已结束，无需终止。');return;}clearInterval(runTimers[id]);t.status='stopped';t.finishedAt=new Date().toISOString();t.lastProgressAt=t.finishedAt;t.phase='用户终止任务';t.summaryGenerating=false;persist();closeModal();render();toast('任务已终止，已返回结果保留。');return;case 'merge-export':return tcStartMerge();case 'tc-merge-submit':return tcSubmitMerge();case 'tc-artifact':return tcDownloadArtifact(t,Number(el.dataset.index));case 'tc-export-zip':return tcDownloadZip(t);case 'tc-export-refresh':return tcRefreshExport();case 'tc-export-retry':return tcRetryExport(t);}return tcBase.handleAction(action,el);};
window.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-tc-check')){e.stopImmediatePropagation();const id=el.dataset.tcCheck,t=state.tasks.find(x=>x.id===id);if(!t)return;if(el.checked&&!tcSelectable(t))return;taskChecked=el.checked?[...new Set([...taskChecked,id])]:taskChecked.filter(x=>x!==id);render();return;}if(el.dataset.tcFilter){e.stopImmediatePropagation();const k=el.dataset.tcFilter,val=el.value;if(k==='size')tcView.size=+val;else tcView[k]=val;if(tcView.from&&tcView.to&&tcView.from>tcView.to){tcView[k]='';toast('起始日期不能晚于结束日期。');}state.taskPage=1;tcView.scroll=0;render();return;}},true);
// An internally scrolling list keeps filters and pagination visible in embedded frames.
window.addEventListener('scroll',e=>{if(e.target?.matches?.('.tc-table-scroll'))tcView.scroll=e.target.scrollTop;},true);
render=function(){tcBase.render();if(state.view==='tasks'){const el=$('.tc-table-scroll');if(el)el.scrollTop=tcView.scroll;}};
// Merge export is its own task, with immutable source/configuration snapshots.
function tcMergeData(tasks){const columns=['来源任务'],records=[];for(const t of tasks){const matrix=exportRows(t),headers=(matrix[0]||[]).map(String);for(const h of headers)if(!columns.includes(h))columns.push(h);for(const cells of matrix.slice(1)){const row={'来源任务':t.name};headers.forEach((h,i)=>{row[h]=cells[i]??'';});records.push(row);}}return {columns,records};}
function tcCanExportTask(t){return (t.ids||[]).every(id=>{const d=file(id);return d&&!d.deleted&&auditFileAccess(d).read&&auditFileAccess(d).download;});}
function tcStartMerge(){const tasks=taskChecked.map(id=>state.tasks.find(t=>t.id===id)).filter(Boolean);if(tasks.length<2)return toast('请至少选择两项相同工具的分析任务。');if(tasks.some(t=>tcMerge(t)||tcResolve(t)!==tcResolve(tasks[0])||(t.agent_id&&tasks[0].agent_id&&t.agent_id!==tasks[0].agent_id)))return toast('请选择同一工具的任务。');if(tasks.some(tcBusy))return toast('有任务仍在处理中，请等待结束后合并导出，避免遗漏结果。');if(tasks.some(t=>!tcCanExportTask(t)))return toast('来源资料包含已移除或无下载权限的文件，请先核对权限。');const data=tcMergeData(tasks);if(!data.records.length)return toast('所选任务尚无可导出的结果，请先查看任务信息。');openModal('tc-merge',{ids:tasks.map(t=>t.id),data,name:tool(tcResolve(tasks[0])).name+' · 合并结果',notes:'',files:['excel'],scope:'header',langs:{header:'zh',export:'en',comment:'zh'},size:Math.max(1,data.records.length),days:7,execution:'background',mapping:data.columns.map((h,i)=>({source:h,header:{zh:h,en:'field_'+(i+1)},export:{zh:h,en:'field_'+(i+1)},comment:{zh:h,en:'field_'+(i+1)}})),error:''});}
function tcMergeModal(){const p=modalData,scope=p.scope,lang=p.langs[scope];return modalFrame('合并导出结果','同一工具的任务可合并，字段不同时合并字段并保留空值。','<div class="tc-merge-summary"><span>来源任务 <strong>'+p.ids.length+'</strong> 项</span><span>已有结果 <strong>'+p.data.records.length+'</strong> 行</span><span>字段 <strong>'+p.mapping.length+'</strong> 个</span></div><div class="tc-merge-form"><label class="field"><span>导出任务名称 <b class="red">*</b></span><input data-tc-draft="name" value="'+E(p.name)+'" maxlength="100"></label><label class="field"><span>任务备注（选填）</span><input data-tc-draft="notes" value="'+E(p.notes)+'" maxlength="500"></label><div class="tc-merge-form-row"><fieldset><legend>导出格式</legend><label><input type="checkbox" data-tc-format="excel" '+(p.files.includes('excel')?'checked':'')+'>Excel</label><label><input type="checkbox" data-tc-format="sql" '+(p.files.includes('sql')?'checked':'')+'>神通数据库 SQL</label></fieldset><label>每文件最多行数<input aria-label="每文件最多行数" type="number" min="1" max="100000" data-tc-draft="size" value="'+p.size+'"></label><label>下载有效天数<input aria-label="下载有效天数" type="number" min="1" max="7" data-tc-draft="days" value="'+p.days+'"></label><label>提交后查看<select data-tc-draft="execution"><option value="background" '+(p.execution==='background'?'selected':'')+'>返回任务列表</option><option value="immediate" '+(p.execution==='immediate'?'selected':'')+'>查看导出进度</option></select></label></div></div><div class="tc-mapping-head"><h3>字段映射</h3><select aria-label="字段映射用途" data-tc-map="scope">'+[['header','Excel 表头'],['export','SQL 字段名'],['comment','SQL 字段注释']].map(([k,n])=>'<option value="'+k+'" '+(scope===k?'selected':'')+'>'+n+'</option>').join('')+'</select><select aria-label="字段映射语言" data-tc-map="lang"><option value="zh" '+(lang==='zh'?'selected':'')+'>中文</option><option value="en" '+(lang==='en'?'selected':'')+'>英文</option></select></div><p class="hint">英文初始值为字段编号，可手动调整；三种映射分别保存。来源任务和来源文件随结果保留。</p><div class="tc-mapping-scroll"><table class="table"><thead><tr><th>来源字段</th><th>导出名称</th></tr></thead><tbody>'+p.mapping.map((r,i)=>'<tr><td>'+E(r.source)+'</td><td><input aria-label="导出名称 '+E(r.source)+'" data-tc-mapping="'+i+'" value="'+E(r[scope][lang])+'" maxlength="100"></td></tr>').join('')+'</tbody></table></div><p class="error" id="tc-merge-error" role="alert">'+E(p.error||'')+'</p>','<span class="tc-modal-note">仅合并已返回结果，不启动新的 AI 分析</span><div class="row">'+B('取消','close-modal')+B('创建导出任务','tc-merge-submit','primary')+'</div>','tc-merge-dialog');}
function tcSubmitMerge(){const p=modalData,tasks=p.ids.map(id=>state.tasks.find(t=>t.id===id));let err='';if(!p.name.trim())err='请填写导出任务名称。';else if(!p.files.length)err='请至少选择一种导出格式。';else if(!Number.isInteger(+p.size)||+p.size<1||+p.size>100000)err='每文件行数请输入 1–100000 的整数。';else if(!Number.isInteger(+p.days)||+p.days<1||+p.days>7)err='下载有效天数请输入 1–7 的整数。';else if(tasks.some(t=>!t||tcBusy(t)||!tcCanExportTask(t)))err='来源任务或资料权限发生变化，请重新选择。';for(const scope of ['header','export','comment']){if(err)break;if(scope==='header'&&!p.files.includes('excel')||scope!=='header'&&!p.files.includes('sql'))continue;const names=p.mapping.map(r=>r[scope][p.langs[scope]].trim());if(names.some(n=>!n))err='导出字段名称不能为空。';else if(scope!=='comment'&&new Set(names.map(n=>n.toLowerCase())).size!==names.length)err='导出字段名称存在重复，请调整映射。';else if(scope==='export'&&names.some(n=>!/^\p{L}[\p{L}\p{N}_]*$/u.test(n)||n.length>60))err='SQL 字段名需以字母或汉字开头，仅含字母、汉字、数字、下划线，且不超过60字。';}if(err){p.error=err;paintModal();return;}const data=tcMergeData(tasks),t={id:'M'+Date.now(),kind:'merge-export',toolId:tcResolve(tasks[0]),name:p.name.trim(),notes:p.notes.trim(),created:new Date().toISOString(),status:'running',progress:0,phase:'正在整理结果与字段映射',sourceTaskIds:[...p.ids],sourceTasks:tasks.map(t=>({id:t.id,name:t.name,toolId:tcResolve(t)})),ids:[...new Set(tasks.flatMap(t=>t.ids||[]))],data:structuredClone(data),config:{files:[...p.files],mapping:structuredClone(p.mapping),langs:{...p.langs},rowsPerFile:+p.size,expireDays:+p.days,execution:p.execution},result:[]};state.tasks.unshift(t);taskChecked=[];closeModal();tcView.group='all';state.taskStatus='all';state.taskTool='all';state.taskQuery='';state.taskPage=1;tcView.kind='all';tcView.scroll=0;nav('tasks');if(p.execution==='immediate')openModal('tc-export-detail',{id:t.id});persist();tcScheduleExport(t);toast('导出任务已创建，来源分析结果保留。');}
function tcCell(v){return typeof v==='object'?JSON.stringify(v):String(v??'');}
function tcBuildArtifacts(t){const {mapping,langs,rowsPerFile,files}=t.config,rows=t.data.records,entries=[],enc=s=>new TextEncoder().encode(s),ident=s=>'"'+s.replaceAll('"','""')+'"',literal=v=>"'"+tcCell(v).replaceAll("'","''")+"'",headers=mapping.map(m=>m.header[langs.header]),sqlFields=mapping.map(m=>m.export[langs.export]),base=t.name.replace(/[\\/:*?"<>|]/g,'_');if(files.includes('sql')){const ddl='CREATE TABLE "analysis_results" (\n'+sqlFields.map(n=>'  '+ident(n)+' TEXT').join(',\n')+'\n);\n'+mapping.map((m,i)=>'COMMENT ON COLUMN "analysis_results".'+ident(sqlFields[i])+' IS '+literal(m.comment[langs.comment])+';').join('\n');entries.push([base+'-建表.sql',enc(ddl),'text/plain;charset=utf-8']);}for(let start=0;start<rows.length;start+=rowsPerFile){const chunk=rows.slice(start,start+rowsPerFile),index=Math.floor(start/rowsPerFile)+1;if(files.includes('excel')){const wb=XLSX.utils.book_new(),matrix=[headers,...chunk.map(r=>mapping.map(m=>tcCell(r[m.source])))];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(matrix),'合并结果');entries.push([base+'-'+index+'.xlsx',new Uint8Array(XLSX.write(wb,{type:'array',bookType:'xlsx'})),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);}if(files.includes('sql')){const sql=chunk.map(r=>'INSERT INTO "analysis_results" ('+sqlFields.map(ident).join(', ')+') VALUES ('+mapping.map(m=>literal(r[m.source])).join(', ')+');').join('\n');entries.push([base+'-数据-'+index+'.sql',enc(sql),'text/plain;charset=utf-8']);}}return entries;}
function tcExportUsable(t){if(!t||t.status!=='completed')return false;if(t.expiresAt&&new Date(t.expiresAt)<new Date()){toast('下载有效期已过，请在导出详情中刷新下载有效期。');return false;}if(!tcCanExportTask(t)){toast('来源资料权限发生变化，当前不能下载。');return false;}return true;}
function tcDownloadArtifact(t,index){if(!tcExportUsable(t))return;const e=tcBuildArtifacts(t)[index];if(e)download(e[0],e[1],e[2]);}
function tcDownloadZip(t){if(!tcExportUsable(t))return;download(t.name.replace(/[\\/:*?"<>|]/g,'_')+'.zip',tcZip(tcBuildArtifacts(t).map(([n,b])=>[n,b])),'application/zip');}
function tcExportDetail(t){if(!t)return modalFrame('导出任务不存在','','<p>任务记录已被移除。</p>',B('关闭','close-modal'),'small');return modalFrame('合并导出任务',E(t.name),'<div class="tc-info-status">'+tag(...tcLabel(t))+'<span>合并 '+(t.sourceTaskIds?.length||0)+' 项'+E(tool(tcResolve(t))?.name||'')+'任务</span></div>'+tcProgress(t)+(t.status==='completed'?'<div class="tc-export-files"><h3>导出文件 <strong>'+(t.artifacts?.length||0)+'</strong></h3>'+simpleTable(['文件名称','操作'],(t.artifacts||[]).map((a,i)=>[E(a.name),A('下载文件','tc-artifact','data-id="'+E(t.id)+'" data-index="'+i+'"')]),true)+'<p class="hint">下载有效期至 '+tcDate(t.expiresAt)+'；仅合并已返回结果，未完成或失败部分不计入结果行。</p></div>':'<p class="hint">'+(t.status==='stopped'?'导出已终止；来源分析任务及结果保留。':t.status==='failed'?'文件未生成：'+E(t.error||'请核对配置后重新导出。'):'完成后在此下载 Excel 或 SQL，原分析结果保留。')+'</p>')+'<h3>来源分析任务</h3><ul class="tc-source-tasks">'+(t.sourceTasks||[]).map(s=>'<li>'+E(s.name)+(state.tasks.some(x=>x.id===s.id)?A('查看结果','tc-result','data-id="'+E(s.id)+'"'):'<span class="hint">来源任务记录已移除</span>')+'</li>').join('')+'</ul><details class="tc-export-config"><summary>查看导出配置与字段映射</summary><p>格式：'+E(t.config.files.join(' / '))+' · 每文件 '+t.config.rowsPerFile+' 行 · 下载有效 '+t.config.expireDays+' 天</p>'+simpleTable(['来源字段','Excel 表头','SQL 字段名','SQL 字段注释'],t.config.mapping.map(m=>[E(m.source),E(m.header[t.config.langs.header]),E(m.export[t.config.langs.export]),E(m.comment[t.config.langs.comment])]),true)+'</details>',B('关闭','close-modal')+B(I('refresh','icon-sm')+(t.status==='completed'?'刷新下载有效期':'刷新状态'),'tc-export-refresh','sm')+(t.status==='failed'?B('重试导出','tc-export-retry','primary','data-id="'+E(t.id)+'"'):'')+(t.status==='completed'?B(I('download','icon-sm')+'打包下载','tc-export-zip','primary','data-id="'+E(t.id)+'"'):''),'tc-export-dialog');}
window.addEventListener('input',e=>{const el=e.target;if(modal!=='tc-merge')return;const p=modalData;if(el.dataset.tcDraft)p[el.dataset.tcDraft]=el.value;else if(el.hasAttribute('data-tc-mapping'))p.mapping[+el.dataset.tcMapping][p.scope][p.langs[p.scope]]=el.value;},true);
window.addEventListener('change',e=>{const el=e.target;if(modal!=='tc-merge')return;const p=modalData;if(el.dataset.tcDraft){p[el.dataset.tcDraft]=el.value;return;}if(el.dataset.tcFormat){p.files=el.checked?[...new Set([...p.files,el.dataset.tcFormat])]:p.files.filter(x=>x!==el.dataset.tcFormat);return;}if(el.dataset.tcMap){e.stopImmediatePropagation();if(el.dataset.tcMap==='scope')p.scope=el.value;else p.langs[p.scope]=el.value;paintModal();}},true);
// Queue state cannot continue after the browser-local execution session has ended.
state.tasks.forEach(t=>{if(t.status==='queued'&&!t.demoSnapshot){t.status='stopped';t.phase='执行会话已中断，资料与配置保留';}});
render();
document.addEventListener('toggle',e=>{const detail=e.target;if(!detail.matches?.('.tc-row-more')||!detail.open)return;document.querySelectorAll('.tc-row-more[open]').forEach(d=>{if(d!==detail)d.open=false;});const r=detail.querySelector('summary').getBoundingClientRect(),menu=detail.querySelector('.tc-row-menu'),h=menu.offsetHeight;menu.style.left=Math.max(4,Math.min(innerWidth-204,r.right-196))+'px';menu.style.top=(r.bottom+h+8>innerHeight?Math.max(4,r.top-h-4):r.bottom+4)+'px';},true);
// ZIP filenames are UTF-8; legacy CFB writers lose Chinese names in archive headers.
function tcZip(entries){const enc=new TextEncoder(),parts=[],central=[];let offset=0,total=0;const crc=b=>{let n=-1;for(const v of b){n^=v;for(let k=0;k<8;k++)n=(n>>>1)^((n&1)?0xedb88320:0);}return (n^-1)>>>0;};for(const [filename,raw] of entries){const name=enc.encode(filename),data=raw instanceof Uint8Array?raw:new Uint8Array(raw),c=crc(data),head=new Uint8Array(30),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint32(14,c,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);parts.push(head,name,data);const ch=new Uint8Array(46),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x0800,true);cv.setUint32(16,c,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.push(ch,name);offset+=head.length+name.length+data.length;total+=ch.length+name.length;}const end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,entries.length,true);ev.setUint16(10,entries.length,true);ev.setUint32(12,total,true);ev.setUint32(16,offset,true);const out=new Uint8Array(offset+total+22);let n=0;for(const part of [...parts,...central,end]){out.set(part,n);n+=part.length;}return out;}
window.addEventListener('keydown',e=>{const d=[...document.querySelectorAll('.tc-row-more[open],.tc-filter-more[open]')].find(d=>d.contains(e.target));if(!d)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();d.open=false;d.querySelector('summary').focus();return;}if(!d.matches('.tc-row-more')||!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...d.querySelectorAll('.tc-row-menu button:not(:disabled)')],i=buttons.indexOf(document.activeElement);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:e.key==='ArrowDown'?(i+1)%buttons.length:(i-1+buttons.length)%buttons.length]?.focus();},true);
document.addEventListener('click',e=>{document.querySelectorAll('.tc-row-more[open],.tc-filter-more[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;});});
window.addEventListener('scroll',e=>{if(e.target?.matches?.('.tc-table-scroll'))document.querySelectorAll('.tc-row-more[open]').forEach(d=>d.open=false);},true);

function tcScheduleExport(t){t.startedAt=new Date().toISOString();t.lastProgressAt=t.startedAt;let tick=0;runTimers[t.id]=setInterval(()=>{if(t.status!=='running'){clearInterval(runTimers[t.id]);return;}tick++;t.lastProgressAt=new Date().toISOString();t.progress=tick*25;if(tick>=4){clearInterval(runTimers[t.id]);try{t.artifacts=tcBuildArtifacts(t).map(([name,,mime])=>({name,mime}));t.status='completed';t.phase='导出完成';t.completed=new Date().toISOString();t.expiresAt=new Date(Date.now()+t.config.expireDays*86400000).toISOString();}catch(error){t.status='failed';t.progress=0;t.phase='生成导出文件失败';t.error=String(error?.message||'文件生成失败，请检查字段内容后重新创建导出任务。');}persist();}if(state.view==='tasks')render();if(modal==='tc-export-detail'&&modalData.id===t.id)paintModal();},200);}

function tcRefreshExport(){const t=state.tasks.find(t=>t.id===modalData.id);if(!t)return;if(t.status!=='completed'){paintModal();return toast('已刷新导出任务状态。');}if(!tcCanExportTask(t))return toast('来源资料权限发生变化，当前不能刷新下载。');const retention=new Date(t.completed||t.created).getTime()+30*86400000;if(Date.now()>=retention)return toast('导出文件已超过30天保留期，请重新创建导出任务。');t.expiresAt=new Date(Math.min(retention,Date.now()+t.config.expireDays*86400000)).toISOString();persist();paintModal();toast('下载有效期已刷新。');}
function tcRetryExport(t){if(!t||t.status!=='failed')return;if(!tcCanExportTask(t))return toast('来源资料权限发生变化，请先核对权限。');t.status='running';t.progress=0;t.phase='正在重新生成导出文件';t.retryCount=(t.retryCount||0)+1;t.error='';persist();tcScheduleExport(t);paintModal();if(state.view==='tasks')render();}
